# ======================================================= PART 2: trunking
def node(i, label, t, x, y, sub=None, pos=None):
    d = dict(id=i, label=label, type=t, x=x, y=y)
    if sub: d["sub"] = sub
    if pos: d["pos"] = pos
    return d
